solution.js:
const karte = document.getElementById("karte");
const merkenKnopf = document.getElementById("merken-knopf");
const entfernenKnopf = document.getElementById("entfernen-knopf");
merkenKnopf.addEventListener("click", function () {
  karte.classList.add("gemerkt");
});
entfernenKnopf.addEventListener("click", function () {
  karte.classList.remove("gemerkt");
});

